Write a simple function in CUDA
Certainly! Here's a simple CUDA function that adds two vectors element-wise:

```cuda
#include <cuda_runtime.h>
#include <stdio.h>

// CUDA kernel function to add two vectors
__global__ void vectorAdd(float *a, float *b, float *c, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n)
    {
        c[i] = a[i] + b[i];
    }
}

int main()
{
    int n = 1000000;  // Size of vectors
    size_t size = n * sizeof(float);

    // Allocate host memory
    float *h_a = (float *)malloc(size);
    float *h_b = (float *)malloc(size);
    float *h_c = (float *)malloc(size);

    // Initialize host arrays
    for (int i = 0; i < n; i++)
    {
        h_a[i] = 1.0f;
        h_b[i] = 2.0f;
    }

    // Allocate device memory
    float *d_a, *d_b, *d_c;
    cudaMalloc((void **)&d_a, size);
    cudaMalloc((void **)&d_b, size);
    cudaMalloc((void **)&d_c, size);

    // Copy host memory to device
    cudaMemcpy(d_a, h_a, size, cudaMemcpyHostToDevice);
    cudaMemcpy(d_b, h_b, size, cudaMemcpyHostToDevice);

    // Launch CUDA kernel
    int threadsPerBlock = 256;
    int blocksPerGrid = (n + threadsPerBlock - 1) / threadsPerBlock;
    vectorAdd<<<blocksPerGrid, threadsPerBlock>>>(d_a, d_b, d_c, n);

    // Copy result back to host
    cudaMemcpy(h_c, d_c, size, cudaMemcpyDeviceToHost);

    // Verify the result
    for (int i = 0; i < n; i++)
    {
        if (fabs(h_c[i] - 3.0f) > 1e-5)
        {
            fprintf(stderr, "Result verification failed at element %d!\n", i);
            exit(EXIT_FAILURE);
        }
    }

    printf("Vector addition successful!\n");

    // Free device memory
    cudaFree(d_a);
    cudaFree(d_b);
    cudaFree(d_c);

    // Free host memory
    free(h_a);
    free(h_b);
    free(h_c);

    return 0;
}
```

This CUDA program does the following:

1. It defines a CUDA kernel function `vectorAdd` that adds corresponding elements of two input vectors and stores the result in a third vector.

2. In the `main` function, it:
   - Allocates memory for the vectors on both the host (CPU) and device (GPU).
   - Initializes the input vectors on the host.
   - Copies the input data from the host to the device.
   - Launches the CUDA kernel to perform the vector addition on the GPU.
   - Copies the result back from the device to the host.
   - Verifies the result.
   - Frees allocated memory.

3. The CUDA kernel is launched with a specific number of blocks and threads per block to parallelize the computation.

This is a basic example of how to write and use a CUDA function. Remember that to compile and run this code, you need to have the CUDA toolkit installed and use the NVIDIA CUDA compiler (nvcc).
